import type {CSSProperties, ReactNode} from 'react';
import React, {useCallback, useMemo, useRef} from 'react';

import {Button, Popup, getConfig} from '@gravity-ui/uikit';

import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import {cnTrackerSelect} from './TrackerSelect.classname';
import {ItemsList} from './components/ItemsList';
import {Search} from './components/Search';
import {usePopupHeight} from './hooks/usePopupHeight';
import {useSubmitHotkey} from './hooks/useSubmitHotkey';
import {defaultMessages} from './i18n';
import type {TrackerSelectGroup, TrackerSelectItemValueBase} from './types';

import './TrackerSelect.scss';

export type TrackerSelectProps<
    Value extends TrackerSelectItemValueBase = TrackerSelectItemValueBase,
> = {
    groups?: TrackerSelectGroup<Value>[];
    onItemUnpin?: (id: string) => void;
    onSearchChange?: React.ChangeEventHandler<HTMLInputElement>;
    onSubmit?: () => void;
    onReset?: () => void;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    activeItemId?: string;
    showSearch?: boolean;
    showSubmit?: boolean;
    showReset?: boolean;
    submitButtonText?: string;
    resetButtonText?: string;
    popupClassName?: string;
    className?: string;
    subHeader?: ReactNode;
    submitDisabled?: boolean;
} & Parameters<typeof ItemsList>[0];

export const TrackerSelect = <Value extends TrackerSelectItemValueBase>({
    groups,
    onSubmit,
    onReset,
    open,
    onOpenChange,
    onSearchChange,
    showSearch = true,
    showSubmit = true,
    showReset = false,
    submitButtonText,
    resetButtonText,
    popupClassName,
    className,
    subHeader,
    submitDisabled = false,
    ...itemListProps
}: TrackerSelectProps<Value>) => {
    const [searchValue, setSearchValue] = React.useState('');
    const anchorRef = useRef<HTMLDivElement>(null);
    const config = getConfig();
    const {t} = useLocalizedString(defaultMessages, config.lang);

    const filteredGroups = useMemo(() => {
        if (!searchValue) {
            return groups;
        }

        const lowerSearchValue = searchValue.toLowerCase();

        return groups
            ?.map((group) => {
                const filteredItems = Object.entries(group.items ?? {}).reduce(
                    (res, [key, item]) => {
                        if (item.display.toLowerCase().includes(lowerSearchValue)) {
                            return {...res, [key]: item};
                        }
                        return res;
                    },
                    {},
                );

                return {...group, items: filteredItems};
            })
            .filter((group) => Object.keys(group.items ?? {}).length > 0);
    }, [groups, searchValue]);

    const handleSearchChange = useCallback(
        (event: React.ChangeEvent<HTMLInputElement>) => {
            setSearchValue(event.target.value);
            onSearchChange?.(event);
        },
        [onSearchChange],
    );

    const handleOpenChange = useCallback(
        (newOpen: boolean) => {
            onOpenChange(newOpen);
            if (!newOpen) {
                setSearchValue('');
            }
        },
        [onOpenChange],
    );

    const handleSubmit = useCallback(() => {
        onSubmit?.();
        onOpenChange(false);
    }, [onSubmit, onOpenChange]);

    const handleReset = useCallback(() => {
        onReset?.();
        setSearchValue('');
    }, [onReset]);

    useSubmitHotkey(handleSubmit, open);

    const popupMaxHeight = usePopupHeight(anchorRef, 'bottom-start');

    const popupStyle: CSSProperties = useMemo(
        () => ({
            maxHeight: popupMaxHeight ? `${popupMaxHeight}px` : 'auto',
        }),
        [popupMaxHeight],
    );

    const searchDesktop = useMemo(() => {
        return showSearch ? (
            <Search
                autoFocus={true}
                value={searchValue}
                onChange={handleSearchChange}
                placeholder={t('searchPlaceholder')}
            />
        ) : null;
    }, [showSearch, searchValue, handleSearchChange, t]);

    const itemList = useMemo(() => {
        return <ItemsList groups={filteredGroups} {...itemListProps} />;
    }, [filteredGroups, itemListProps]);

    const popupContent = useMemo(() => {
        return (
            <div className={cnTrackerSelect(null, className)}>
                {subHeader}
                <div className={cnTrackerSelect('body')}>{itemList}</div>
                {showSubmit && (
                    <div className={cnTrackerSelect('actions')}>
                        {showReset && (
                            <Button
                                view="flat"
                                size="l"
                                className={cnTrackerSelect('submit')}
                                width="max"
                                onClick={handleReset}
                            >
                                {resetButtonText || t('reset')}
                            </Button>
                        )}
                        <Button
                            view="action"
                            size="l"
                            className={cnTrackerSelect('submit')}
                            width="max"
                            onClick={handleSubmit}
                            disabled={submitDisabled}
                        >
                            {submitButtonText || t('submit')}
                        </Button>
                    </div>
                )}
            </div>
        );
    }, [
        className,
        subHeader,
        itemList,
        showSubmit,
        showReset,
        handleSubmit,
        handleReset,
        submitButtonText,
        resetButtonText,
        submitDisabled,
        t,
    ]);

    return (
        <div ref={anchorRef}>
            <Popup
                open={open}
                onOpenChange={handleOpenChange}
                placement="bottom-start"
                className={cnTrackerSelect(null, popupClassName)}
                anchorElement={anchorRef.current}
                style={popupStyle}
            >
                <>
                    {searchDesktop}
                    {popupContent}
                </>
            </Popup>
        </div>
    );
};
